# Example: Medical entity recognition
# Custom entities: DISEASE, MEDICATION, SYMPTOM, TEST

custom_data = [
    {
        "text": "Patient diagnosed with hypertension and prescribed lisinopril.",
        "entities": [
            {"start": 24, "end": 36, "label": "DISEASE"},
            {"start": 51, "end": 61, "label": "MEDICATION"}
        ]
    },
    {
        "text": "Blood pressure test showed elevated readings.",
        "entities": [
            {"start": 0, "end": 19, "label": "TEST"}
        ]
    }
]

print("🏥 Custom Medical NER Data:\n")
for item in custom_data:
    print(f"Text: {item['text']}")
    print("Entities:")
    for ent in item['entities']:
        text_span = item['text'][ent['start']:ent['end']]
        print(f"  {text_span} → {ent['label']}")
    print()
